import{_ as t,o as a,c as s,a0 as o}from"./chunks/framework.D4fUSYzX.js";const f=JSON.parse('{"title":"ADR 0066: A fresh state file starts the Ticket list grouped by repository","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0066-a-fresh-state-file-starts-the-ticket-list-grouped-by-repository.md","filePath":"adr/0066-a-fresh-state-file-starts-the-ticket-list-grouped-by-repository.md"}'),i={name:"adr/0066-a-fresh-state-file-starts-the-ticket-list-grouped-by-repository.md"};function r(n,e,l,h,d,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0066-a-fresh-state-file-starts-the-ticket-list-grouped-by-repository" tabindex="-1">ADR 0066: A fresh state file starts the Ticket list grouped by repository <a class="header-anchor" href="#adr-0066-a-fresh-state-file-starts-the-ticket-list-grouped-by-repository" aria-label="Permalink to &quot;ADR 0066: A fresh state file starts the Ticket list grouped by repository&quot;">​</a></h1><p>Status: accepted Date: 2026-09-29</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR 0058 made the grouping axis factory state on the state file, per section, and chose the flat list - the axis at <code>none</code> - as the axis a fresh state file starts with. That choice was natural when the flat list was the only list the plane drew: the default was the list itself.</p><p>The flat list is still one press of Tab away from any split, but it shows no structure at all, and the operator works the list by its Groups. The repository split is the first rung of the cycle after the flat list and the fact every ticket carries, so a newly configured plane should come up showing the work the way the operator reads it, not the way the plane used to draw it.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>A fresh state file seeds the Ticket section&#39;s axis at <code>repository</code>.</strong> The state migration that adds the axis table (the v20 to v21 migration) writes <code>(&#39;tickets&#39;, &#39;repository&#39;)</code> for a file that does not yet hold the table, so a newly configured app opens with the Ticket list split by repository, the headers on screen and the Action bar naming the axis before any press.</p><p><strong>A stored axis always wins.</strong> A state file that already holds a row for the Ticket section keeps whatever axis the operator left there, including the <code>none</code> the earlier migration seeded. The migration writes a row only where the table is new; it never rewrites a stored axis, and a restart finds the split where the operator left it (ADR 0058).</p><p><strong>The no-row fallback keeps the flat list.</strong> <code>DEFAULT_GROUPING_AXIS</code> is what a plane reads when the state file names no row for the section or names a value the plane does not. It stays <code>none</code>: the production plane always runs on a state file, so the fallback serves only the in-memory plane and a hand-edited file, and those keep the list the plane drew before the split existed (ADR 0058).</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Keep the flat list the fresh default.</strong> It is the list the plane used to draw, but it shows no structure, and an operator who wants the structure presses Tab once at every fresh boot.</li><li><strong>Turn the no-row fallback to <code>repository</code> as well.</strong> One constant, two answers avoided, but the in-memory plane - the one the frame tests and the preview boot - would re-sort with it, and no operator sees the fallback in a freshly configured app, because that app has a file.</li><li><strong>Default to another axis.</strong> Source, task, state, and position each hide part of the list&#39;s facts for a fact only some tickets carry; repository is the fact every ticket carries and the first rung of the cycle, so it is the split the operator reaches first anyway.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A newly configured app opens with the Ticket list split by repository, the headers on screen and the Action bar naming the axis before any press.</li><li>An existing state file is untouched by the change: the stored axis wins, and a file seeded at <code>none</code> by the earlier migration stays flat until the operator presses Tab.</li><li>A file that predates the axis table migrates to <code>repository</code> now instead of <code>none</code>, because the table it receives is the new table.</li><li>The cycle is unchanged: <code>none</code> is one press of Tab away from <code>repository</code>, and the bar&#39;s rule is unchanged - the flat list states no axis, and a split names it.</li><li>The in-memory plane and a file with a missing or invalid row keep reading the flat list (ADR 0058), and a plane with no state file keeps its axis in memory for the run, the way it always did.</li></ul>',13)])])}const u=t(i,[["render",r]]);export{f as __pageData,u as default};
